SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱瞻基", "aliases": ["明宣宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宣宗，洪熙元年（1425年）六月，朱瞻基即皇帝位。", "biography": null, "status": "draft", "id": "888fc961-674c-52bf-b645-1351d5637434"}, {"name": "方政", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "方政会兵出塞。", "biography": null, "status": "draft", "id": "19078ba6-caff-52e6-9baf-69e2d58fd0de"}, {"name": "阿台（明初蒙古汗）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "阿台（明初蒙古汗）为明廷使者传谕对象。", "biography": null, "status": "draft", "id": "c6b6247f-4e08-5b2c-a145-429e48060519"}, {"name": "朵儿只伯", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "朵儿只伯为明廷使者传谕对象。", "biography": null, "status": "draft", "id": "3490fd6e-748a-59b0-a2d6-98c46783f7db"}, {"name": "王骥", "aliases": ["王驥"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，宣德9年（年号对照1434年）三月，王骥出任兵部尚书。", "biography": null, "status": "draft", "id": "4a558c65-f1f5-51f5-90df-5aa57564c8bb"}, {"name": "魏源", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，宣德10年（年号对照1435年）七月，魏源出任刑部尚书。", "biography": null, "status": "draft", "id": "d9e5aeb1-dd8b-5699-b831-44527c49489a"}, {"status": "draft", "name": "胡安国", "aliases": [], "era": "北宋", "birth_year": null, "death_year": null, "description": "宋中书舍人，1126年参与荐举。", "biography": null, "id": "b6075d0f-8814-5fef-b5b1-be62606d7358"}, {"name": "沈（蔡元定季子）", "aliases": [], "era": "南宋", "birth_year": null, "death_year": null, "description": "蔡元定季子，原文仅名沈，1196年随父徒步赴道州。", "biography": null, "status": "draft", "id": "75110b41-25e0-5881-93bf-f7e5887c1bbf"}, {"status": "draft", "name": "真德秀", "aliases": [], "era": "南宋", "birth_year": null, "death_year": null, "description": "宋太学学官，嘉定初入朝论和议、士风。", "biography": null, "id": "dc5d6a3d-48fe-50a5-86c1-b4b8fde08f22"}, {"name": "柴车", "aliases": ["柴車"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统5年（年号对照1440年）二月，柴车从陕西被召回任职，随即返乡省亲。", "biography": null, "status": "draft", "id": "55a68f00-9d84-5661-8c06-9bf22e7430c6"}, {"name": "沐晟", "aliases": ["沐景茂"], "era": "明", "birth_year": null, "death_year": null, "description": "沐晟率军在爱子江交战。", "biography": null, "status": "draft", "id": "525263d4-8c61-52a8-a6e9-265b6ac50d2a"}, {"name": "思任发", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "思任发为明军征讨对象。", "biography": null, "status": "draft", "id": "98ce9322-c7cd-5041-b4aa-37cc7d6ec513"}, {"name": "胡濙", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，宣德元年（年号对照1426年）四月，胡濙出任礼部尚书。", "biography": null, "status": "draft", "id": "032dda5f-5482-59da-837e-59a422bbaa04"}, {"name": "刘中敷", "aliases": ["劉中敷"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统元年（年号对照1436年），刘中敷出任户部尚书（原文月份缺少月数）。", "biography": null, "status": "draft", "id": "1fa6e6c4-3a0e-504a-ab00-b492ed916052"}, {"name": "陈智", "aliases": ["陳智"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统元年（年号对照1436年）六月，陈智出任右都御史。", "biography": null, "status": "draft", "id": "6246fdb6-8ccb-5700-8d07-aeb13aee1e89"}, {"name": "王通（明代成山侯）", "aliases": ["成山侯"], "era": "明", "birth_year": null, "death_year": null, "description": "王通赴陕西赈济饥民。", "biography": null, "status": "draft", "id": "f94e24e9-3278-51e4-895d-513be2a33e0d"}, {"name": "王翱", "aliases": ["王翺"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰3年（年号对照1452年）二月，王翱结束陕西巡抚职务，返回都察院。", "biography": null, "status": "draft", "id": "285fc3e7-4cbc-5d1a-bb90-b79c366ef275"}]'::jsonb)
