INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明宣宗神主入祀太庙", "description": "正统二年正月甲午，朝廷将明宣宗朱瞻基的神主入祀太庙。", "start_year": 1437, "end_year": 1437, "time_original": "正统二年正月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "57a4ae8e-b117-5262-bda0-dddf2b6bef94"}, {"title": "方政、杨洪会合宁夏和甘肃兵力出塞", "description": "正统二年正月己亥，大同总兵官方政与都指挥杨洪会合宁夏、甘肃的兵力，出塞征讨阿台和朵儿只伯。", "start_year": 1437, "end_year": 1437, "time_original": "正统二年正月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e7946b29-d711-5356-90f4-8f04e98541db"}, {"title": "明廷审录在押囚犯", "description": "正统二年三月甲午，朝廷审录在押囚犯。", "start_year": 1437, "end_year": 1437, "time_original": "正统二年三月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b6f2fa9f-59e8-5656-bb24-10c39f98d7e9"}, {"title": "御史金敬奉命安抚大名、河南和陕西流民", "description": "正统二年三月戊午，朝廷派御史金敬安抚大名及河南、陕西离乡的百姓。", "start_year": 1437, "end_year": 1437, "time_original": "正统二年三月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9d128ee3-51d2-5dc3-9b4e-53951c7b9333"}, {"title": "明廷免除河南受灾地区田粮", "description": "正统二年四月，朝廷免除河南受灾地区应缴田粮。", "start_year": 1437, "end_year": 1437, "time_original": "正统二年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "76f55d5a-d86e-5e8a-85c3-f9e1ecc4029b"}, {"title": "王骥外出处理甘肃边务", "description": "正统2年（年号对照1437年）五月，王骥外出处理甘肃边务。", "start_year": 1437, "end_year": 1437, "time_original": "正统2年（年号对照1437年）五月；公元年核为1437年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "e8b22f0c-b6ff-53ea-a0c0-da95836fdc22"}, {"title": "魏源整顿大同边务", "description": "正统2年（年号对照1437年）五月，魏源整顿大同边务。", "start_year": 1437, "end_year": 1437, "time_original": "正统2年（年号对照1437年）五月；公元年核为1437年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "222cab41-031c-52b5-b1ff-fafd2b67177a"}, {"title": "明廷豁免平凉等府旱灾所涉夏税", "description": "正统二年五月丁未，朝廷免征陕西平凉等六府旱灾所涉的夏税。", "start_year": 1437, "end_year": 1437, "time_original": "正统二年五月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "39e61229-5620-56a6-b957-c522dbc31edd"}, {"title": "明廷将胡安国、蔡沈、真德秀列入孔子庙庭从祀", "description": "正统二年六月乙亥，朝廷决定将宋代儒者胡安国、蔡沈和真德秀列入孔子庙庭从祀。", "start_year": 1437, "end_year": 1437, "time_original": "正统二年六月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "333aa43f-d6a1-5ce8-ac3f-5a2f754a7d30"}, {"title": "贾谅、郑辰奉命救济河南、江北饥民", "description": "正统二年六月庚辰，明廷派副都御史贾谅与侍郎郑辰到河南、江北赈济饥民。", "start_year": 1437, "end_year": 1437, "time_original": "正统二年六月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7ab0e349-8a10-5e92-98d4-1ae19cf63eb3"}, {"title": "任礼奉命任总兵官，率部征讨阿台与朵儿只伯", "description": "正统二年十月甲子，明廷任命任礼为总兵官，蒋贵、赵安为副总兵，率部征讨阿台、朵儿只伯。柴车、曹翼和罗亨信参赞军务，王骥与王贵负责督军。", "start_year": 1437, "end_year": 1437, "time_original": "正统二年十月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5096f9bf-6550-5f4b-bf23-ce9be59cfcae"}, {"title": "明廷赈济河南饥民并豁免税粮", "description": "正统二年十一月乙巳，朝廷救济河南的饥民，并免除当地受灾所涉税粮。", "start_year": 1437, "end_year": 1437, "time_original": "正统二年十一月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "096e8e75-cfe4-50f4-8d81-785c5bc731a4"}, {"title": "本纪汇记正统二年多地来贡", "description": "正统二年，琉球中山、撒马儿罕、暹罗、土鲁番、瓦剌和哈密入贡。 按原历纪年，事情发生在公元1437至1438年之间。", "start_year": null, "end_year": null, "time_original": "正统二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d833477c-b3c7-581d-a182-2abffa1f2d42"}, {"title": "京师发生地震", "description": "正统三年三月己亥，京师发生地震。", "start_year": 1438, "end_year": 1438, "time_original": "正统三年三月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d68d23c1-8c1d-5711-adfc-a3d55575271a"}, {"title": "明廷救济陕西饥民", "description": "正统三年三月辛丑，朝廷赈济陕西的饥民。", "start_year": 1438, "end_year": 1438, "time_original": "正统三年三月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4a7fade4-7c53-5b39-b49b-0817daa02a45"}, {"title": "王骥等击败阿台与朵儿只伯所部", "description": "正统三年四月乙卯，王骥、任礼、蒋贵和赵安击败阿台、朵儿只伯所部。明军追至黑泉后返回。", "start_year": 1438, "end_year": 1438, "time_original": "正统三年四月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7a8d1cba-4baa-57d4-89eb-abdff28f0d62"}, {"title": "明廷设立大同马市", "description": "正统三年四月癸未，朝廷在大同设立马市。", "start_year": 1438, "end_year": 1438, "time_original": "正统三年四月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2ccc8119-c576-584a-9c15-7b1c135652fe"}, {"title": "明廷因旱灾复核中央和地方疑案", "description": "正统三年六月癸酉，朝廷因旱灾命复核中央和地方的疑难案件。", "start_year": 1438, "end_year": 1438, "time_original": "正统三年六月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d6607a50-65ab-532e-aa04-e87fa048a91f"}, {"title": "方政、张荣等奉命会合沐晟、沐昂讨伐思任发", "description": "正统三年六月乙亥，朝廷命方政、张荣与征南将军沐晟、右都督沐昂一同率兵征讨麓川的思任发。", "start_year": 1438, "end_year": 1438, "time_original": "正统三年六月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8f36b559-26eb-5bc6-b76e-1d1fdafdff48"}, {"title": "胡濙被投入监狱，随后获释", "description": "正统3年（年号对照1438年）七月，胡濙被投入监狱，随后获释。", "start_year": 1438, "end_year": 1438, "time_original": "正统3年（年号对照1438年）七月；公元年核为1438年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "b43285fa-9de2-582b-97de-6486e4171630"}, {"title": "刘中敷被投入监狱，不久获释", "description": "正统3年（年号对照1438年）七月，刘中敷被投入监狱，不久获释。", "start_year": 1438, "end_year": 1438, "time_original": "正统3年（年号对照1438年）七月；公元年核为1438年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "b24cd403-9b3d-50ae-b6af-5c9919011c99"}, {"title": "明廷令部分罪囚交银赎罪，以银换米救荒", "description": "正统三年八月乙亥，陕西发生饥荒。朝廷准杂犯死罪及以下罪囚交银赎罪，由边地官员用银换米。", "start_year": 1438, "end_year": 1438, "time_original": "正统三年八月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a9109d0c-645b-5b92-b306-6988f29f84d4"}, {"title": "明廷免除两畿、湖广积欠的赋税", "description": "正统三年九月癸巳，朝廷豁免两畿和湖广积欠的赋税。", "start_year": 1438, "end_year": 1438, "time_original": "正统三年九月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dad1ec9c-665d-5e0e-889e-b74f3dd4ceec"}, {"title": "明廷再次赈济陕西饥民", "description": "正统三年十月癸丑，朝廷再次救济陕西饥民。", "start_year": 1438, "end_year": 1438, "time_original": "正统三年十月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8c54f1d7-fc1a-5600-89db-6029b7a8a2d8"}, {"title": "魏源再次被投入监狱", "description": "正统3年（年号对照1438年）十二月，魏源再次被投入监狱。原历日期只能确定在公元1438年至1439年之间，保留发生范围。", "start_year": null, "end_year": null, "time_original": "正统3年（年号对照1438年）十二月；发生于公元1438至1439年之间，原文未标具体日。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "ba0380b6-4b5a-5317-be59-d3eb06fea32d"}, {"title": "陈智被投入监狱", "description": "正统3年（年号对照1438年）十二月，陈智被投入监狱。原历日期只能确定在公元1438年至1439年之间，保留发生范围。", "start_year": null, "end_year": null, "time_original": "正统3年（年号对照1438年）十二月；发生于公元1438至1439年之间，原文未标具体日。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "1048fe5e-4318-53a9-b7fe-a8e4b561a6c6"}, {"title": "榜葛剌进献本纪称作麒麟的动物，百官上表庆贺", "description": "正统三年，榜葛剌向明廷进献本纪写作麒麟的动物，中央和地方官员上表庆贺。 按原历纪年，事情发生在公元1438至1439年之间。", "start_year": null, "end_year": null, "time_original": "正统三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c0d8c8fe-6249-5a47-85cf-01befb1e2808"}, {"title": "本纪汇记正统三年多地入贡", "description": "正统三年，琉球中山、暹罗、占城、瓦剌向明廷进贡。 按原历纪年，事情发生在公元1438至1439年之间。", "start_year": null, "end_year": null, "time_original": "正统三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "04b53490-c560-5bd8-9da7-cdb4da6cffee"}, {"title": "方政在大寨作战获胜，追至空泥时败亡", "description": "正统四年正月壬午，方政在大寨击败麓川一方，追至空泥后战败身亡。", "start_year": 1439, "end_year": 1439, "time_original": "正统四年正月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7b88205e-6f9c-57cf-9bef-bfc9df6a8e0a"}, {"title": "萧授率部平息贵州计砂战事", "description": "正统四年二月丁巳，本纪记总兵官萧授出兵平息贵州计砂一带与明廷的战事。", "start_year": 1439, "end_year": 1439, "time_original": "正统四年二月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2a7af44c-4832-5508-a784-b5141cbd117b"}, {"title": "魏源获释出狱", "description": "正统4年（年号对照1439年）闰二月，魏源获释出狱。", "start_year": 1439, "end_year": 1439, "time_original": "正统4年（年号对照1439年）闰二月；公元年核为1439年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "436a998e-a5ab-590b-83c7-41d4c41e59bb"}, {"title": "陈智获释出狱", "description": "正统4年（年号对照1439年）闰二月，陈智获释出狱。", "start_year": 1439, "end_year": 1439, "time_original": "正统4年（年号对照1439年）闰二月；公元年核为1439年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "6a80ec12-b50a-5f71-bc92-0ff998c65069"}, {"title": "明廷宽免王通和马骐弃守交阯的罪责", "description": "正统四年闰二月辛丑，朝廷同时宽免王通和马骐因弃交阯所负的罪责。", "start_year": 1439, "end_year": 1439, "time_original": "正统四年闰二月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2678c674-c43f-53c1-ad04-a533feef9955"}, {"title": "明廷颁布大赦", "description": "正统四年三月己酉，朝廷下诏大赦天下。", "start_year": 1439, "end_year": 1439, "time_original": "正统四年三月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6c706c09-a6a8-5281-b831-babe6fff23fe"}, {"title": "明廷授予施槃等人不同等第的进士资格", "description": "正统四年三月壬子，朝廷授予施槃等人不同等第的进士资格。", "start_year": 1439, "end_year": 1439, "time_original": "正统四年三月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2d80a9f8-e1df-594a-93b0-f8445f95d9b6"}, {"title": "辽王朱贵烚被废为庶人", "description": "正统四年三月庚申，明廷废去辽王朱贵烚的王爵，将他降为庶人。", "start_year": 1439, "end_year": 1439, "time_original": "正统四年三月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "l